INSERT dbo._ROCK9086_LavaBackup (Tbl, Id, Col, OldValue) SELECT 'ReportField', x.[Id], 'Selection', x.[Selection] FROM [ReportField] x WHERE x.[Id] = 71196
  AND NOT EXISTS (SELECT 1 FROM dbo._ROCK9086_LavaBackup b WHERE b.Tbl = 'ReportField' AND b.Id = x.[Id] AND b.Col = 'Selection');
UPDATE [ReportField] SET [Selection] = REPLACE(REPLACE([Selection], N'{% if (CriminalCheckStatus == ''Approved'') or (CriminalCheckStatus == ''Reapproved'') %}', N'{% if CriminalCheckStatus == ''Approved'' or CriminalCheckStatus == ''Reapproved'' %}'), N'{% if  Attendance1stVerifiedDate| Date:''M/d/yyyy'' | DateDiff:''Now'',''d'' > 186 %}', N'{% assign daysSinceFirstAttend = Attendance1stVerifiedDate | DateDiff:''Now'',''d'' %}{% if daysSinceFirstAttend > 186 %}')
WHERE [Id] = 71196
  AND (DATALENGTH([Selection]) - DATALENGTH(REPLACE([Selection], N'{% if (CriminalCheckStatus == ''Approved'') or (CriminalCheckStatus == ''Reapproved'') %}', N''))) / DATALENGTH(N'{% if (CriminalCheckStatus == ''Approved'') or (CriminalCheckStatus == ''Reapproved'') %}') = 1
  AND (DATALENGTH([Selection]) - DATALENGTH(REPLACE([Selection], N'{% if  Attendance1stVerifiedDate| Date:''M/d/yyyy'' | DateDiff:''Now'',''d'' > 186 %}', N''))) / DATALENGTH(N'{% if  Attendance1stVerifiedDate| Date:''M/d/yyyy'' | DateDiff:''Now'',''d'' > 186 %}') = 1;
