INSERT dbo._ROCK9086_LavaBackup (Tbl, Id, Col, OldValue) SELECT 'AttributeValue', x.[Id], 'Value', x.[Value] FROM [AttributeValue] x WHERE x.[Id] = 418777152 AND x.[AttributeId] = 1201 AND x.[EntityId] = 9054
  AND NOT EXISTS (SELECT 1 FROM dbo._ROCK9086_LavaBackup b WHERE b.Tbl = 'AttributeValue' AND b.Id = x.[Id] AND b.Col = 'Value');
UPDATE [AttributeValue] SET [Value] = REPLACE(REPLACE(REPLACE([Value], N'{% if row.Age == '''' or row.Age == null %}', N'{% if row.Age == null %}'), N'{% if row.Visits == '''' or row.Visits == null %}', N'{% if row.Visits == null %}'), N'{% if row.Communion == '''' or row.Communion == ''false'' or row.Communion == ''False'' or row.Communion == null %}
                                <i class="fa fa-times"></i>
                            {% else %}
                                <i class="fa fa-check"></i>
', N'{% assign communion = row.Communion | AsBoolean %}{% if communion %}
                                <i class="fa fa-check"></i>
                            {% else %}
                                <i class="fa fa-times"></i>
')
WHERE [Id] = 418777152 AND [AttributeId] = 1201 AND [EntityId] = 9054
  AND (DATALENGTH([Value]) - DATALENGTH(REPLACE([Value], N'{% if row.Age == '''' or row.Age == null %}', N''))) / DATALENGTH(N'{% if row.Age == '''' or row.Age == null %}') = 1
  AND (DATALENGTH([Value]) - DATALENGTH(REPLACE([Value], N'{% if row.Visits == '''' or row.Visits == null %}', N''))) / DATALENGTH(N'{% if row.Visits == '''' or row.Visits == null %}') = 1
  AND (DATALENGTH([Value]) - DATALENGTH(REPLACE([Value], N'{% if row.Communion == '''' or row.Communion == ''false'' or row.Communion == ''False'' or row.Communion == null %}
                                <i class="fa fa-times"></i>
                            {% else %}
                                <i class="fa fa-check"></i>
', N''))) / DATALENGTH(N'{% if row.Communion == '''' or row.Communion == ''false'' or row.Communion == ''False'' or row.Communion == null %}
                                <i class="fa fa-times"></i>
                            {% else %}
                                <i class="fa fa-check"></i>
') = 1;
INSERT @log VALUES ('AttributeValue', 418777152, 'int-vs-empty', @@ROWCOUNT);

UPDATE l SET [Rows] = -1 FROM @log l WHERE l.[Rows] = 0 AND NOT EXISTS (
    SELECT 1 FROM WorkflowType x WHERE l.Tbl = 'WorkflowType' AND x.Id = l.Id UNION ALL
    SELECT 1 FROM HtmlContent x WHERE l.Tbl = 'HtmlContent' AND x.Id = l.Id UNION ALL
    SELECT 1 FROM WorkflowActionForm x WHERE l.Tbl = 'WorkflowActionForm' AND x.Id = l.Id UNION ALL
    SELECT 1 FROM SystemCommunication x WHERE l.Tbl = 'SystemCommunication' AND x.Id = l.Id UNION ALL
    SELECT 1 FROM Block x WHERE l.Tbl = 'Block' AND x.Id = l.Id UNION ALL
    SELECT 1 FROM ReportField x WHERE l.Tbl = 'ReportField' AND x.Id = l.Id UNION ALL
    SELECT 1 FROM AttributeValue x JOIN @avkeys k ON k.Id = x.Id AND k.AttributeId = x.AttributeId AND k.EntityId = x.EntityId
        WHERE l.Tbl = 'AttributeValue' AND x.Id = l.Id);
SELECT * FROM @log ORDER BY Tbl, Id;
IF EXISTS (SELECT 1 FROM @log WHERE [Rows] NOT IN (1, -1)) PRINT 'WARNING: some statements did not update exactly one row - review before committing.';
IF @DryRun = 0 AND EXISTS (SELECT 1 FROM @log WHERE [Rows] NOT IN (1, -1))
BEGIN ROLLBACK; THROW 50000, 'ROCK9086 pass 13: a guarded update did not match exactly one row; nothing committed.', 1; END

